<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { api, apiMessage } from '@/api/client'; import type { Plan } from '@/types';
const plans=ref<Plan[]>([]);const error=ref('');const busy=ref(false);const router=useRouter();const today=new Date().toLocaleDateString('sv-SE');
const draft=reactive({name:'',description:'',startDate:today,endDate:today,overallTagName:'总计',overallTagColor:'#002FA7'});
async function load(){plans.value=(await api.get<Plan[]>('/plans')).data;}
async function create(){busy.value=true;error.value='';try{const {data}=await api.post<Plan>('/plans',draft);await router.push(`/plans/${data.id}`);}catch(e){error.value=apiMessage(e);}finally{busy.value=false;}}
onMounted(()=>load().catch(e=>error.value=apiMessage(e)));
</script>
<template><div class="page"><section class="page-head"><div><p class="eyebrow">PLANS / CRUD</p><h1>计划与标签</h1></div><p>一个计划拥有独立日期范围、总标签、分类标签和任务。</p></section><p v-if="error" class="error-text">{{error}}</p><div class="split-layout"><section class="section"><header class="section-title"><h2>我的计划</h2><span>{{plans.length}}</span></header><article v-for="plan in plans" :key="plan.id" class="plan-card" @click="router.push(`/plans/${plan.id}`)"><div><strong>{{plan.name}}</strong><p>{{plan.startDate}}—{{plan.endDate}}</p></div><div class="plan-progress"><span>{{plan.completedCount}}/{{plan.taskCount}}</span><i><b :style="{width:plan.taskCount?`${plan.completedCount/plan.taskCount*100}%`:'0%'}"/></i></div></article><p v-if="!plans.length" class="empty">创建第一个计划后，它会显示在这里。</p></section><form class="editor-card" @submit.prevent="create"><p class="eyebrow">NEW PLAN</p><h2>新建计划</h2><label>计划名称<input v-model="draft.name" required maxlength="120" /></label><label>说明<textarea v-model="draft.description" rows="3"/></label><div class="form-grid"><label>开始日期<input v-model="draft.startDate" type="date" required /></label><label>结束日期<input v-model="draft.endDate" type="date" required /></label></div><div class="form-grid"><label>总标签<input v-model="draft.overallTagName" required /></label><label>标签颜色<input v-model="draft.overallTagColor" type="color" /></label></div><button class="btn primary" :disabled="busy">{{busy?'正在创建…':'创建并进入计划'}}</button></form></div></div></template>
